import{_ as r,a0 as n,w as o,s as p,I as e,x as a,a1 as s,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse(`{"title":"數據科學家的開源社區分析指南 | LCTT x X-CMD","titleTemplate":false,"description":"數據科學家的開源社區分析指南 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"數據科學家的開源社區分析指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"數據科學家的開源社區分析指南 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20221206.3 ⭐️⭐️ A data scientist's guide to open source community analysis","title":"數據科學家的開源社區分析指南","tag":"202303","desc":""},"relativePath":"202303/20221206.3 ⭐️⭐️ A data scientist's guide to open source community analysis.md","filePath":"[post].md"}`),u={name:"202303/20221206.3 ⭐️⭐️ A data scientist's guide to open source community analysis.md"};function m(g,t,h,f,b,x){const i=n("Link");return o(),p("div",null,[t[18]||(t[18]=e("h1",{id:"數據科學家的開源社區分析指南",tabindex:"-1"},[a("數據科學家的開源社區分析指南 "),e("a",{class:"header-anchor",href:"#數據科學家的開源社區分析指南","aria-label":"Permalink to “數據科學家的開源社區分析指南”"},"​")],-1)),t[19]||(t[19]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/19/155043lcx6bxqw5ci5gpgi.jpg",alt:""})],-1)),t[20]||(t[20]=e("blockquote",null,[e("p",null,"研究一下這個框架，來建立你自己的開源項目的數據分析。")],-1)),t[21]||(t[21]=e("p",null,"在數據分析的黃金時代，開源社區也不能免俗。大家都熱衷於將一些華麗的數字放到演示幻燈片上，但如果你掌握了正確的分析方法，這些信息可以為你帶來更大的價值。",-1)),e("p",null,[t[1]||(t[1]=a("或許你認為作為一名 ",-1)),s(i,{href:"https://enterprisersproject.com/article/2022/9/data-scientist-day-life?intcmp=7013a000002qLH8AAM"},{default:l(()=>[...t[0]||(t[0]=[a("數據科學家",-1)])]),_:1}),t[2]||(t[2]=a("，我會告訴你數據分析和自動化能為你的社區決策提供信息。但實際上，情況恰恰相反。利用數據分析來構建你現有的開源社區知識，吸收其他的知識，並發現潛在的偏見和沒有思考過的觀點。你或許是實施社區活動的專家，而你那些同事則是代碼方面的專家。當你們每個人都在自己的知識背景下將信息可視化時，你們都可以從這些信息中受益。",-1))]),t[22]||(t[22]=d('<p>讓我們來面對現實吧。每個人都有一千零一件事情要做，而且總感覺一天的時間永遠不夠用。如果需要幾個小時才能得到你的社區的答案，你就不可能有足夠的精力去解決這些事情。但是，花時間創建一個全面發展的可視化項目，可以幫助你時刻掌握你所關心的社區的不同方面，這就將你從精疲力盡中解放了出來。</p><p>隨着“數據驅動”思維的盛行，圍繞開源社區的信息寶庫可能是一種祝福，也可能是一種詛咒。下面我將分享一些方法，告訴你如何從數據乾草堆中挑出有價值的信息。</p><h3 id="你的預期是什麼" tabindex="-1">你的預期是什麼？ <a class="header-anchor" href="#你的預期是什麼" aria-label="Permalink to “你的預期是什麼？”">​</a></h3><p>當考慮一個指標時，首先要明確你想提供的觀點。以下是幾個可能涉及的概念：</p><p><strong>告知性和影響性的行動：</strong> 你的社區是否存在某個領域尚未被理解？你是否已邁出第一步？你是否試圖確定特定方向？你是否正在衡量現有倡議的效果？</p><p><strong>暴露需要改進的領域和突出優勢：</strong> 有時你想宣傳你的社區，突出它的優勢，特別是在試圖證明商業影響或為項目宣傳時。然而，當涉及到向社區內部傳遞信息時，你通常需要從一堆指標中精準的找到你們的缺點，以此來幫助你們改進。雖然突出優點並非不可取，但需要在適當的時間和地點。不要把優勢指標作為社區內部的拉拉隊，告訴每個人都有多棒，而是要與外界分享，以獲得認可或推廣。</p><p><strong>社區和商業影響：</strong> 數字和數據是許多企業的語言。但是這可能使得為你的社區進行宣傳並真正展示其價值變得異常困難。數據可以成為用他們的語言説話的一種方式，並展示他們想看到的東西，以使你數據背後的潛在含義能夠被有效轉達。另一個角度是對開源的整體影響。你的社區是如何影響他人和生態系統的？</p><p>這些觀點並非非此即彼，而是相互關聯的。適當的框架將有助於創造一個更深思熟慮的衡量標準。</p><p><img src="https://opensource.com/sites/default/files/2022-11/datascience-machinelearning-workflow.jpg" alt="數據科學和機器學習的工作流程"></p><p>當人們談論通用的數據科學或機器學習工作時，通常會描述這樣的工作流程。我將重點關注第一步，即編寫問題和度量標準，並簡要提及第二步。從數據科學的角度來看，這個演示可以被視為這個步驟的一個案例研究。這一步有時會被忽視，但你的分析的實際價值始於此。你不能一天醒來就知道要看什麼。從理解你想知道什麼和你所擁有的數據開始，逐步實現更加深度的數據分析。</p><h3 id="_3個開源數據分析用例" tabindex="-1">3個開源數據分析用例 <a class="header-anchor" href="#_3個開源數據分析用例" aria-label="Permalink to “3個開源數據分析用例”">​</a></h3><p>以下是您在開源數據分析過程中可能遇到的三種不同場景。</p><h4 id="場景-1-現有數據分析" tabindex="-1">場景 1：現有數據分析 <a class="header-anchor" href="#場景-1-現有數據分析" aria-label="Permalink to “場景 1：現有數據分析”">​</a></h4><p>假設你開始進行分析，並且已經知道你將要研究的內容對你或你的社區是有用的。那麼你該如何提高分析的價值呢？這裏的想法是建立在“傳統”的開源社區分析基礎之上。假設你的數據表明，在項目的整個生命週期內，你共有 120 個貢獻者。這是你可以放在幻燈片上的價值，但你不能從中做出決策。從僅有一個數字到獲得洞見，逐步採取措施。例如，你可以從相同的數據中將貢獻者分為活躍和流失的貢獻者（那些已經有一段時間沒有做出貢獻的貢獻者），以獲得更深入的瞭解。</p><h4 id="場景-2-社區活動的影響測量" tabindex="-1">場景 2：社區活動的影響測量 <a class="header-anchor" href="#場景-2-社區活動的影響測量" aria-label="Permalink to “場景 2：社區活動的影響測量”">​</a></h4><p><img src="https://opensource.com/sites/default/files/2022-11/goals-impact.png" alt="目標和影響"></p><p>針對聚會、會議或其他任何社區外聯活動，你如何看待你的影響力和目標？這兩個步驟實際上互相影響。一旦你確定了活動的目標，就要確定可以用什麼來檢測效果。這些信息有助於設定活動的目標。在活動開始時，很容易陷入模糊的計劃而非具體的計劃的陷阱中。</p><h4 id="場景3-形成新的影響分析區" tabindex="-1">場景3：形成新的影響分析區 <a class="header-anchor" href="#場景3-形成新的影響分析區" aria-label="Permalink to “場景3：形成新的影響分析區”">​</a></h4><p><img src="https://opensource.com/sites/default/files/2022-11/new-analysis-areas.png" alt="新的分析區"></p><p>當你從頭開始進行數據分析時，就會出現這種情況。前面的例子是這個工作流程的不同部分。這個工作流程是一個不斷發展的循環；你可以隨時進行改進或擴展。基於這個概念，以下是你應該經歷的必要步驟。在本文的後面，將會有三個不同的例子，展示這種方法在現實世界中的應用。</p><h4 id="第一步-分解關注區和視角" tabindex="-1">第一步：分解關注區和視角 <a class="header-anchor" href="#第一步-分解關注區和視角" aria-label="Permalink to “第一步：分解關注區和視角”">​</a></h4><p>首先，想像一下魔法 8 球——你可以問任何問題，搖一搖，就能得到答案的玩具。考慮你的分析領域。如果你能立即得到任何答案，那會是什麼？</p><p>接下來，考慮數據。從你的魔法 8 球問題中，哪些數據源可能與問題或關注領域有關？</p><p>在數據背景下，哪些問題可以回答，讓你更接近你提出的魔法 8 球問題？需要注意的是，如果你試圖將所有的數據彙集在一起，你必須考慮到所做出的假設。</p><h4 id="第二步-將問題轉化為指標" tabindex="-1">第二步：將問題轉化為指標 <a class="header-anchor" href="#第二步-將問題轉化為指標" aria-label="Permalink to “第二步：將問題轉化為指標”">​</a></h4><p>以下是第一步中每個子問題的處理過程：</p><ul><li>選擇所需的具體數據點。</li><li>確定可視化以實現目標分析。</li><li>假設這些信息的影響。</li></ul><p>接下來，引入社區提供反饋並觸發迭代開發過程。這個協作部分可能就是真正的魔力所在。最好的想法通常是在將一個概念帶給某個人時產生的，會激發他們的靈感，這是你或他們無法想像的。</p><h4 id="第三步-分析實踐" tabindex="-1">第三步：分析實踐 <a class="header-anchor" href="#第三步-分析實踐" aria-label="Permalink to “第三步：分析實踐”">​</a></h4><p>這一步是你開始處理你所創建的指標或可視化的影響。</p><p>首先要考慮的是，這個度量標準是否符合當前對社區的瞭解。</p><ul><li>如果<strong>是</strong>：是否有假設得出的結果？</li><li>如果<strong>不是</strong>：你需要進一步調查，是否這是一個潛在的數據或計算問題，或者只是先前被誤解的社區的一部分。</li></ul><p>一旦你確定你的分析足夠穩定，可以開始在信息上實施社區倡議。當你正在進行分析以確定下一步最佳步驟時，你應該確定衡量倡議成功的具體方法。</p><p>現在，觀察這些由你的指標提供信息的社區倡議。確定是否可以用你之前建立的成功衡量指標觀察到影響。如果沒有，可以考慮以下幾點：</p><ul><li>你是否在衡量正確的事情？</li><li>倡議戰略是否需要調整？</li></ul><h3 id="分析區的例子-新貢獻者" tabindex="-1">分析區的例子：新貢獻者 <a class="header-anchor" href="#分析區的例子-新貢獻者" aria-label="Permalink to “分析區的例子：新貢獻者”">​</a></h3><h4 id="魔法-8-球問題是什麼" tabindex="-1">魔法 8 球問題是什麼？ <a class="header-anchor" href="#魔法-8-球問題是什麼" aria-label="Permalink to “魔法 8 球問題是什麼？”">​</a></h4><ul><li>如何分析哪些人為持續的貢獻者？</li></ul><h4 id="我有什麼數據可以納入分析區和魔法-8-球問題" tabindex="-1">我有什麼數據可以納入分析區和魔法 8 球問題？ <a class="header-anchor" href="#我有什麼數據可以納入分析區和魔法-8-球問題" aria-label="Permalink to “我有什麼數據可以納入分析區和魔法 8 球問題？”">​</a></h4><ul><li>倉庫存在哪些貢獻者的活動，包括時間戳？</li></ul><p>現在你有了這些信息和一個魔法 8 球問題，把分析分成幾個子部分執行。這個想法與上述步驟 2 和 3 相關。</p><p><strong>子問題 1:</strong> “人們是怎麼進入這個項目的”</p><p>這個問題的目的是先看看新的貢獻者在做什麼。</p><p><strong>數據：</strong> GitHub 上的首次貢獻隨時間推移的數據（議題、PR、評論等）。</p><p><img src="https://opensource.com/sites/default/files/2022-11/first-time-contributions-per-quarter.png" alt="每季度首次貢獻圖表"></p><p><strong>可視化：</strong> 按季度劃分的首次貢獻條形圖。</p><p><strong>潛在的意義：</strong> 在你與其他社區成員交談後，進一步檢查按季度細分的信息，以及貢獻者是否為重複貢獻者或僅僅是路過。你可以看到人們進來的時候在做什麼，以及這是否能告訴你他們是否會留下來。</p><p><img src="https://opensource.com/sites/default/files/2022-11/driveby-contributions-per-quarter.png" alt="每季度路過貢獻圖標"></p><p><strong>從這些信息中瞭解到的可以採取的行動。</strong></p><ul><li>目前的文檔是否能夠幫助到最常見的新手？你能不能更好地幫助和支持新人朋友，這將有助於他們中更多的人留下來？</li><li>是否有一個貢獻領域在整體上並不常見，但重複貢獻者卻集中在這個區域？也許 PR 是重複貢獻者的一個常見區域，但大多數人卻不在這個區域工作。</li></ul><p><strong>行動項目：</strong></p><ul><li>給 “好的第一個問題” 貼上一致的標籤，並將這些問題鏈接到貢獻文檔中。</li><li>在這些問題上添加一個 PR 夥伴。</li></ul><p><strong>子問題 2：</strong> “我們的代碼庫真的依賴於路過的貢獻者嗎？”</p><p><strong>數據：</strong> GitHub 的貢獻數據。</p><p><img src="https://opensource.com/sites/default/files/2022-11/contributor-types-over-time.png" alt="貢獻者類型隨時間變化的圖表"></p><p><strong>可視化：</strong> “貢獻總額：按路過和重複貢獻者的貢獻進行細分。”</p><p><strong>根據這一信息可能採取的行動。</strong></p><ul><li>這個比例是否達到了項目的目標？很多工作都是由路過貢獻者完成的嗎？這是否是一種未被充分利用的資源，項目是否沒有盡到自己的責任來吸引他們？</li></ul><h3 id="分析-吸取教訓" tabindex="-1">分析：吸取教訓 <a class="header-anchor" href="#分析-吸取教訓" aria-label="Permalink to “分析：吸取教訓”">​</a></h3><p>數字和數據分析並不是“事實”，它們可以支持任何觀點。因此，在處理數據時，內部懷疑者應該非常積極，並進行反覆迭代，以帶來真正的價值。你不希望你的分析只是一個 “yes man”，因此花點時間退一步，評估你所做的假設。</p><p>如果一個指標只是指出了調查的方向，那也是一個巨大的勝利。你不可能看清或想到所有的事情，兔子洞可以是一個好事，對話的起點可以把你帶到一個新的地方。</p><p>有時，你想測量的東西恰恰不在那裏，但你也許能得到有價值的細節。不要假設你有所有的拼圖碎片來獲得你最初問題的準確答案。如果你開始強迫一個答案或解決方案，你會把自己帶入一條由假設引領的危險道路。為分析的方向或目標的改變留出空間，可以讓你獲得比最初的想法更好的洞察力。</p><p>數據只是是一種工具，並不是標準答案，它可以彙集原本無法獲得的見解和信息。將你想知道的東西分解成可管理的小塊，並在此基礎上進行分析，這是最重要的部分。</p><p>開源數據分析是一個很好的例子，説明你必須對所有的數據科學採取謹慎態度。</p><ul><li>主題領域的細微差別是最重要的。</li><li>通過“問什麼/答什麼”的工作過程經常被忽視。</li><li>知道“問什麼”可能是最難的部分，當你想出一些有洞察力和創新的東西時，這比你選擇的任何工具都要重要。</li></ul><p>如果你是一個沒有數據科學經驗的社區成員，正在尋找開始的地方，我希望這些信息能告訴你，你在這個過程中是多麼重要和寶貴。你帶來了社區的洞察力和觀點。如果你是一個數據科學家或實施指標或可視化的人，你必須傾聽你周圍的聲音，即使你也是一個活躍的社區成員。關於數據科學的更多信息列在本文的最後。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>把上面的例子作為建立你自己的開源項目的數據分析的框架。對你的結果有很多問題要問，知道這些問題和它們的答案可以把你的項目引向一個令人興奮和富有成效的方向。</p><hr>',69)),e("p",null,[t[4]||(t[4]=a("via: ",-1)),s(i,{href:"https://opensource.com/article/22/12/data-scientists-guide-open-source-community-analysis"},{default:l(()=>[...t[3]||(t[3]=[a("https://opensource.com/article/22/12/data-scientists-guide-open-source-community-analysis",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=a("作者：",-1)),s(i,{href:"https://opensource.com/users/cdolfi"},{default:l(()=>[...t[5]||(t[5]=[a("Cali Dolfi",-1)])]),_:1}),t[10]||(t[10]=a(" 選題：",-1)),s(i,{href:"https://github.com/lkxed"},{default:l(()=>[...t[6]||(t[6]=[a("lkxed",-1)])]),_:1}),t[11]||(t[11]=a(" 譯者：",-1)),s(i,{href:"https://github.com/Chao-zhi"},{default:l(()=>[...t[7]||(t[7]=[a("Chao-zhi",-1)])]),_:1}),t[12]||(t[12]=a(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=a("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[13]||(t[13]=[a("LCTT",-1)])]),_:1}),t[16]||(t[16]=a(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:l(()=>[...t[14]||(t[14]=[a("Linux中國",-1)])]),_:1}),t[17]||(t[17]=a(" 榮譽推出",-1))])])}const P=r(u,[["render",m]]);export{k as __pageData,P as default};
